def gd(eta, steps):
    # f(x, y) = 5x^2 + y^2/2, so grad f = (10x, y)
    x, y = 1.0, 1.0
    for _ in range(steps):
        x, y = x - eta * 10 * x, y - eta * y
    return round(x, 6), round(y, 6)

for eta in (0.1, 0.25):
    print(eta, gd(eta, 5))

